// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type FinancialStrategyProps = Record<string, any>;

const FinancialStrategy: React.FC<FinancialStrategyProps> = ({
  backgroundColor = "#080c16",
  transparentBackground = false,
  durationInSeconds = 6,
  primaryAccentColor = "#3b82f6",
  secondaryAccentColor = "#93c5fd",
  textColor = "#f8fafc",
  headlineText = "They think in multi-year windows.",
  subheadlineText = "So today's decisions don't create future tax problems.",
  windowCount = 4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser Safety: Extract background transparency logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Responsive values
  const paddingX = width * 0.08;
  const paddingY = height * 0.12;
  const s = Math.min(width, height);

  // Animation Timing
  const textStartFrame = 15;
  const subtextStartFrame = 40;
  const windowStartFrame = 10;

  // Springs & Interpolations
  const textReveal = spring({
    fps,
    frame: frame - textStartFrame,
    config: { damping: 14, stiffness: 80 },
  });

  const subtextReveal = spring({
    fps,
    frame: frame - subtextStartFrame,
    config: { damping: 14, stiffness: 80 },
  });

  const textTranslateY = interpolate(textReveal, [0, 1], [60, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const subtextTranslateY = interpolate(subtextReveal, [0, 1], [40, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Floating effect for the graphic cluster
  const floatY = Math.sin(frame / 30) * (s * 0.02);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceGrotesk,
        flexDirection: "row",
        alignItems: "center",
        paddingLeft: paddingX,
        paddingRight: paddingX,
        paddingTop: paddingY,
        paddingBottom: paddingY,
        transition: "none",
        overflow: "hidden",
      }}
    >
      {/* Left Column: Typography */}
      <div
        style={{
          flex: 1.2,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          gap: height * 0.06,
          zIndex: 10,
          transition: "none",
        }}
      >
        <div style={{ overflow: "hidden", transition: "none" }}>
          <h1
            style={{
              margin: 0,
              fontSize: s * 0.08,
              fontWeight: 700,
              color: textColor,
              lineHeight: 1.2,
              letterSpacing: "-0.02em",
              maxWidth: "18ch",
              opacity: textReveal,
              transform: `translateY(${textTranslateY}px)`,
              transition: "none",
            }}
          >
            {headlineText}
          </h1>
        </div>

        <div style={{ overflow: "hidden", transition: "none" }}>
          <p
            style={{
              margin: 0,
              fontSize: s * 0.045,
              fontWeight: 400,
              color: secondaryAccentColor,
              lineHeight: 1.4,
              maxWidth: "28ch",
              opacity: subtextReveal,
              transform: `translateY(${subtextTranslateY}px)`,
              transition: "none",
            }}
          >
            {subheadlineText}
          </p>
        </div>
      </div>

      {/* Right Column: Abstract Windows Graphic */}
      <div
        style={{
          flex: 1,
          position: "relative",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
          transform: `translateY(${floatY}px)`,
        }}
      >
        {Array.from({ length: windowCount }).map((_, index) => {
          // Staggered timing for each window
          const delay = windowStartFrame + index * 8;
          const windowSpring = spring({
            fps,
            frame: frame - delay,
            config: { damping: 12, stiffness: 90 },
          });

          // Calculations for isometric-like stacking
          const scale = interpolate(windowSpring, [0, 1], [0.5, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const opacity = interpolate(windowSpring, [0, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const size = s * 0.45;
          const offsetStep = s * 0.05;
          const totalOffset = (windowCount - 1) * offsetStep;

          // Center the entire cluster
          const baseX = -totalOffset / 2;
          const baseY = totalOffset / 2;

          const x = baseX + index * offsetStep;
          const y = baseY - index * offsetStep;

          // Progression color from primary to transparent/border
          const progress = index / Math.max(windowCount - 1, 1);
          
          return (
            <div
              key={index}
              style={{
                position: "absolute",
                width: size,
                height: size * 1.2, // Slightly taller "windows"
                borderRadius: size * 0.1,
                border: `2px solid ${primaryAccentColor}`,
                backgroundColor:
                  index === windowCount - 1
                    ? `${primaryAccentColor}22`
                    : `${backgroundColor}E6`, // Slight transparency to see layers below
                boxShadow: `0 20px 40px ${backgroundColor}80`,
                opacity: opacity * (1 - progress * 0.4), // Fade back elements
                transform: `translate(${x}px, ${y}px) scale(${scale})`,
                zIndex: index,
                transition: "none",
                display: "flex",
                flexDirection: "column",
                overflow: "hidden",
                backdropFilter: "blur(4px)",
              }}
            >
               {/* Abstract inner UI/Data lines to represent decisions/strategy */}
               <div style={{ flex: 1, padding: size * 0.1, display: 'flex', flexDirection: 'column', gap: size * 0.05, opacity: 0.5, transition: "none" }}>
                  <div style={{ width: '40%', height: size * 0.02, backgroundColor: primaryAccentColor, borderRadius: size * 0.02, transition: "none" }} />
                  <div style={{ width: '70%', height: size * 0.02, backgroundColor: secondaryAccentColor, borderRadius: size * 0.02, opacity: 0.6, transition: "none" }} />
                  <div style={{ width: '60%', height: size * 0.02, backgroundColor: secondaryAccentColor, borderRadius: size * 0.02, opacity: 0.4, transition: "none" }} />
               </div>
               {/* Bottom accent bar */}
               <div style={{ height: size * 0.05, backgroundColor: primaryAccentColor, transition: "none" }} />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default FinancialStrategy;